import requests
import time

def chamada_segura(url, payload, max_tentativas=3):
    for tentativa in range(max_tentativas):
        try:
            r = requests.post(url, json=payload, timeout=60)

            # Trata 429 e 5xx antes de raise_for_status()
            if r.status_code == 429 or r.status_code >= 500:
                tempo_espera = min(2 ** tentativa, 30)  # Limita máximo de 30s
                time.sleep(tempo_espera)
                continue

            r.raise_for_status()  # Lança exceção para 4xx
