  const [loaded, setLoaded] = useState(false);

  const handleLoad = () => setLoaded(true);

  return (
    <img
      ref={(el) => {
        if (el?.complete) handleLoad();
      }}
      onLoad={handleLoad}
      src={src}
      className={`transition-opacity ${loaded ? 'opacity-100' : 'opacity-0'}`}
    />
  );
};
```

